dtsPropsFor.Button:
/** primary is the single forward action per screen. onDark for deep-leaf surfaces. destructive is the one control allowed to be filled rust — for a click that destroys something, never for merely "important". */
variant?: 'primary' | 'secondary' | 'quiet' | 'onDark' | 'destructive';
/** medium is the default and covers nearly every case. small is for a button inside an already-dense row (it sits under the 48px tap minimum on purpose). large is for a single hero CTA. */
size?: 'small' | 'medium' | 'large';
/** The label. Name the outcome in ordinary words — "Save trip", "Delete" — never a movement verb. */
children?: React.ReactNode;
disabled?: boolean;
/** Defaults to 'button' — set 'submit' only inside a form. */
type?: 'button' | 'submit' | 'reset';
onClick?: React.MouseEventHandler<HTMLButtonElement>;
className?: string;
/** Every other <button> attribute is forwarded. Focus is handled by :focus-visible, not a prop. */
[key: string]: unknown;

dtsPropsFor.Chip:
/** Renders the filled leaf state and sets aria-pressed. */
selected?: boolean;
/** 'saved' renders the plum tag used for kept places. */
tone?: 'default' | 'saved';
children?: React.ReactNode;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
disabled?: boolean;
className?: string;
/** Renders a real <button>; every other button attribute is forwarded. */
[key: string]: unknown;

dtsPropsFor.Tag:
/** 'saved' renders the plum tag used for kept places. */
tone?: 'default' | 'saved';
children?: React.ReactNode;
className?: string;
/** Static and non-interactive — renders a <span>. Use Chip when it triggers something. */
[key: string]: unknown;

dtsPropsFor.Input:
/** Trailing affordance, e.g. the return glyph "\u21b5". */
hint?: string;
/** Renders the rust error border. Set only when the value is actually wrong — never to draw attention. Pair it with a message that names the fix. */
error?: boolean;
/** Escape hatch for the bordered wrapper — e.g. `flex: 1` inside a row. */
wrapperClassName?: string;
value?: string | number;
defaultValue?: string | number;
/** May ask a plain question, but a placeholder is never the only label. */
placeholder?: string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
disabled?: boolean;
readOnly?: boolean;
type?: string;
className?: string;
/** Every other <input> attribute is forwarded to the real input. */
[key: string]: unknown;

dtsPropsFor.Select:
/** The <option> elements. A native select — the closed control is styled, the open menu stays the OS's. */
children?: React.ReactNode;
/** Renders the rust error border. Same rule as Input: only when the selection is actually wrong. */
error?: boolean;
/** Escape hatch for the positioning wrapper — e.g. `flex: 1` inside a row. */
wrapperClassName?: string;
value?: string | number;
defaultValue?: string | number;
onChange?: React.ChangeEventHandler<HTMLSelectElement>;
disabled?: boolean;
className?: string;
/** Every other <select> attribute is forwarded. */
[key: string]: unknown;

dtsPropsFor.Switch:
/** Required. The knob's position is the primary state signal, colour only the second. */
checked: boolean;
/** Required. Fires with the NEXT value. A switch takes effect immediately — there is nothing to confirm. */
onCheckedChange: (checked: boolean) => void;
/** Required. The words beside the track ARE the accessible name — there is no separate label or aria-label. */
children: React.ReactNode;
/** Greys the track in both states and mutes the label; the knob position still carries on/off. */
disabled?: boolean;
className?: string;
[key: string]: unknown;

dtsPropsFor.Logo:
/** primary sits on paper; reversed sits on deep leaf. */
variant?: 'primary' | 'reversed';
/** Mark height in px. At 28 or below the stroke thickens automatically. Never below 24. */
size?: number;
/** Hide for favicons, app icons and stamps. */
showWordmark?: boolean;
className?: string;
style?: React.CSSProperties;
[key: string]: unknown;

dtsPropsFor.Trail:
/** One entry per pass, in order. Exactly one stop should be 'open' — that is where you are. */
stops?: Array<'decided' | 'open' | 'waiting' | 'destination'>;
/** Optional caption per stop, e.g. ['Brainstorm', 'Gather', 'Schedule']. */
labels?: string[];
/** Set on deep-leaf surfaces. */
onDark?: boolean;
/** SVG height in px. Default 46. */
height?: number;
/** Called with the stop index when its label is activated; supplying it makes the labels real buttons. Omit for a decorative trail. 'waiting' stops are never selectable. */
onSelectStop?: (index: number) => void;
className?: string;
[key: string]: unknown;
